import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

const validators: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: validateUserMessage,
  ping: validatePingMessage,
  list_sessions: validateListSessionsMessage,
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = validators[message.type];
  if (!validator) return {valid: false, error: `Unknown message type: ${message.type}`};
  return validator(message);
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateLimitField(limit: unknown): string | null {
  if (limit === undefined) return null;
  if (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 1) {
    return 'list_sessions limit must be a positive integer';
  }
  return null;
}

function validateBeforeField(before: unknown): string | null {
  if (typeof before !== 'object' || before === null || Array.isArray(before)) {
    return 'list_sessions before must be an object';
  }
  const obj = before as Record<string, unknown>;
  if (typeof obj.sessionId !== 'string' || obj.sessionId.length < 1 || obj.sessionId.length > 128) {
    return 'list_sessions before.sessionId must be 1–128 characters';
  }
  if (typeof obj.updatedAt !== 'string' || isNaN(Date.parse(obj.updatedAt))) {
    return 'list_sessions before.updatedAt must be a valid date string';
  }
  return null;
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limitError = validateLimitField(message.limit);
  if (limitError !== null) return {valid: false, error: limitError};

  const beforeError = message.before === undefined ? null : validateBeforeField(message.before);
  if (beforeError !== null) return {valid: false, error: beforeError};

  const result: ListSessionsMessage = {type: 'list_sessions'};
  if (message.limit !== undefined) result.limit = message.limit as number;
  if (message.before !== undefined) {
    const before = message.before as Record<string, unknown>;
    result.before = {updatedAt: before.updatedAt as string, sessionId: before.sessionId as string};
  }
  return {valid: true, data: result};
}

